
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b3lyps_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b3lyps", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.730050922795519e+00, -3.660020583764231e+00, -3.561938119642780e+00, -3.426166907276468e+00, -3.241362557299680e+00, -2.995813184027579e+00, -2.680583642535158e+00, -2.295083353718091e+00, -1.854148021545313e+00, -1.390329421103876e+00, -9.398858216079051e-01, -6.396951990025469e-01, -5.525236876896992e-01, -4.603512891209031e-01, -3.355835458000156e-01, -2.122240467715955e-01, -1.241413082100409e-01, -7.684825466323206e-02, -4.614876234075483e-02, -3.039745691160994e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


